using System.Collections.Generic;
using System.Linq;

namespace Rasa.Data
{
    /// <summary>
    /// The Kraftwerks' recipes, in the client's own shape (shared/crafting.pyo's recipeItemTemplateTable, decoded to
    /// generated_shared_crafting.pyo.json).
    ///
    /// A recipe is a schematic <b>item</b> - its template id is the recipe's id - and it says what the station turns
    /// into what: the inputs (an item template and a quantity each), the result (template and amount), the energy it
    /// costs, how long the station takes in seconds, and the level the player has to be. The first one is the plainest
    /// case: schematic 641 takes 500 of item 1765 and gives 500 of item 28 (standard-grade cartridges), which is why
    /// the same table also carries the cartridges' own exchange.
    ///
    /// This is the client's data rather than authored data, so it lives here beside the other client-derived tables
    /// (ExpPerLevel, AuctionHouseData) instead of in a world table.
    /// </summary>
    public static class CraftingData
    {
        /// <summary>One input: an item template and how many of it the recipe consumes.</summary>
        public readonly struct Input
        {
            public Input(uint itemTemplateId, uint quantity)
            {
                ItemTemplateId = itemTemplateId;
                Quantity = quantity;
            }

            public uint ItemTemplateId { get; }
            public uint Quantity { get; }
        }

        /// <summary>One schematic: what it consumes, what it yields, and what it costs in time and level.</summary>
        public sealed class Recipe
        {
            public uint TemplateId { get; init; }
            public uint EnergyUnitCost { get; init; }
            public uint KraftwerksTimeSeconds { get; init; }
            public uint ResultEntityClassId { get; init; }
            public uint ResultItemTemplateId { get; init; }
            public uint ResultItemAmount { get; init; }
            public uint MinimumPlayerLevel { get; init; }
            public Input[] Inputs { get; init; } = System.Array.Empty<Input>();
        }

