        private static readonly Dictionary<uint, Recipe> ByTemplate =
            Recipes.ToDictionary(recipe => recipe.TemplateId);

        /// <summary>The schematic with that template id, or null when nothing known is one.</summary>
        public static Recipe ForTemplate(uint templateId)
            => ByTemplate.TryGetValue(templateId, out var recipe) ? recipe : null;

        /// <summary>
        /// True when the data is self-consistent; asserted by the tests. Four recipes carry no inputs at all - the
        /// client's own rows have an empty input list - so an empty input list is allowed, but a listed input has to
        /// name an item and a quantity.
        /// </summary>
        public static bool IsSelfConsistent()
            => Recipes.All(recipe => recipe.KraftwerksTimeSeconds > 0
                                     && recipe.ResultItemTemplateId != 0
                                     && recipe.ResultItemAmount > 0
                                     && recipe.MinimumPlayerLevel >= 1
                                     && recipe.Inputs.All(input => input.ItemTemplateId != 0 && input.Quantity > 0));
    }
